    current_field = []
    in_quote = False
    i = 0
    n = len(text)

    while i < n:
        char = text[i]

        if not in_quote:
            if char == '"':
                in_quote = True
                current_field.append(char)
                i += 1
                continue
            elif char == ',':
                if not current_field:
                    return None
                fields.append(''.join(current_field))
                current_field = []
                i += 1
                continue
            else:
                current_field.append(char)
                i += 1
        else:
            if char == '"' and i + 1 < n and text[i+1] == '"':
                # Escaped quote: treat as literal quote
                current_field.append('"')
                i += 2
                continue
            elif char == '"':
                in_quote = False
                if i + 1 < n and text[i+1] == ',':
                    i += 2
                    continue
                elif i == n - 1:
                    return None
                else:
                    # After closing quote, only comma or end allowed
                    if text[i+1] == ',':
                        i += 2
                    else:
                        return None
                if current_field:
                    fields.append(''.join(current_field))
                    current_field = []
            else:
                current_field.append(char)
                i += 1

    # Check if we're at end of input
    if current_field:
        return None

    return fields
